        body: "Technology projects frequently begin with a proposed system or solution.\nWe begin with the requirement.\nBefore automating or replacing a process, we seek to understand why it exists, what it is intended to achieve, who is responsible for it, what controls are required and how success should be measured.\nOur approach follows a simple discipline:",
        flow: ["Requirement", "Objective", "Process", "Responsibility", "Control", "Measure", "Accountability", "Outcome"],
        closing: "This helps prevent organisations from simply reproducing inefficient processes in new technology.",
