            intro: "Dhaabbileen yeroo hunda garee teeknooloojii guutuu keessatti qacaruu hin barbaadan, hin fedhanis.\nSI gareewwan misoomaa addaa kan dhaabbilee maamiltootaa waliin hojjetan ykn dameewwan dhiyeessii teeknooloojii murtaa'aniif itti gaafatamummaa fudhatan ni kenna.\nGareewwan kunneen yeroo barbaachise dandeettii addaa kennuu, waliin immoo dabarsii beekumsaa gara namoota maamilaa mataa isaaniitti deeggaruu danda'u.",
