            intro: "AI-n rakkoo daldalaa furuu qaba, rakkoo ta'uu hin qabu.\nSI dhaabbileen iddoo AI-n gatii dhugaa uumuu danda'u adda baasaniif ni gargaara, ergasii carraa irraa gara hojiirra oolmaatti ce'uuf teeknooloojii, deetaa, bulchiinsaa fi dandeettii hojiirra oolmaa barbaachisu ni kenna.\n\"Eessatti AI fayyadamuu dandeenya?\" jennee hin gaafannu. \"Maal fooyyessuuf yaalla?\" jennee gaafanna.",
