            body: "ESX gabaa sirna qabu kan waraqaaleen gatii ulaagaa guutan itti galanii fi daldalaman ni kenna.\nDhaabbileen hayyamaman bu'a qabeessummaan hirmaachuuf adeemsa hojii, to'annoo, teeknooloojii fi walqunnamtii sirrii ta'e barbaadu.\nSI dhaabbileen barbaachisummaa kana bocanii fi hojiirra oolchaniif ni gargaara.",
