            body: "CSD-n kutaa murteessaa bu'uura gabaa kaappitaalaa Itoophiyaa ta'ee, galmee elektirooniksii abbummaa waraqaa gatii kenna, kaffaltii xumuraa fi adeemsawwan booda-daldalaa walqabatan ni deeggara.\nWaraqaalee gatii sadarkaa abbaa dhugaa irratti galmeessuun abbummaa waraqaa gatii invastaraa tokko sadarkaa faayinaansii dilaalaa, daldalaa ykn baankii invastimantii isaanii irraa addaan baasuudhaan kutaa barbaachisaa eegumsa invastaraa ta'uu danda'a.\nSI dhaabbileen bocaalee herregaa, adeemsawwan hojii, teeknooloojii, walsimsiisa, kaffaltii xumuraa fi walqunnamtii CSD waliin bu'a qabeessummaan walqunnamuuf barbaachisan akka hubataniif fi hojiirra oolchaniif ni gargaara.",
