        body: "Namni hundinuu gadi-fageenya beekumsaa wal fakkaataa hin barbaadu.\nNamni hundinuu beekumsa gahee isaaf ta'u barbaada.\nMiseensi Boordii nageenya saayibarii akkuma injinara nageenyaatti hubachuu hin barbaachisu.\nMiseensi Bulchiinsa Olaanaa kaffaltii xumuraa waraqaa gatii raawwachuu hin barbaachisu, garuu balaa, itti gaafatamummaa, to'annoo fi odeeffannoo bulchiinsaa hojii sana too'achuuf barbaachisan hubachuu qaba.\nInvastarri dhuunfaa baankii invastimantii akkamitti akka hojjetu hubachuu hin barbaachisu, garuu naannoo faayinaansii, gahee hirmaattota garaa garaa fi balaa invastimantii waliin walqabatu hubachuu qaba.\nKanaafuu, SI leenjii gahee, itti gaafatamummaa fi dandeettii barbaachisu irratti bocti, mata duree qofa irratti utuu hin taane.",
        outcomeEyebrow: "Barbaachisummaa irraa gara Bu'aatti",
