          title: "ንመኽር",
          lead: "ንኣገደስቲ ውሳነታት ተመክሮን ምስትውዓልን።",
          body: "ንትካላት ካብ መጀመርታ ሓሳብን ተኻእሎነትን ጀሚሩ ክሳብ ምጥያሽ፣ ፍቓድ ተቖጻጻሪ ኣካል፣ ትግባረ፣ ዕብየትን ለውጥን ኣብ ዘሎ ምሉእ ጉዕዞኦም ንድግፎም።\nደንቢ ዝተሓላለኸ እዩ፣ ዕዳጋታት ይልወጡ፣ ስትራተጂያዊ ውሳነታት ድማ ነዊሕ ዕድመ ዘለዎ ሳዕቤን ክህልዎም ይኽእል። ዓማዊል ኣማራጺታቶም ንኽርድኡ፣ ሓደጋ ንኽመሓደሩን ኣብ ሓበሬታ ዝተመርኮሰ ውሳነ ንኽገብሩን ግብራዊ ተመክሮን ናጻ ፍርድን ነምጽእ። \nክትሰምዑ ትደልዩ ዘይኮነስ ክትፈልጡ ዘለኩም ንነግረኩም።",
