          desc: "ስራሕ ምጅማር መወዳእታ ጉዕዞ ኣይኮነን - ትካል ንገዛእ ርእሱ ብግብሪ ዘረጋግጸሉ ጅማሮ እዩ።\nምስ ዓማዊል ኣብ መወዳእታ ድልውነት ኣሰራርሓ፣ መእተዊ ዕዳጋን ስራሕ ምጅማርን ብሓባር ንሰርሕ፣ ሰባት፣ መስርሕታት፣ ቴክኖሎጂ፣ ቁጽጽርን ምሕደራን ካብ ቀዳማይ መዓልቲ ጀሚሮም ብዉጽኢታውነት ከም ዝሰርሑ ብምሕጋዝ።\nድሕሪ ምጅማር፣ ኣብ ወሳኒ ግዜ ምርግጋእ ቀጻሊ ደገፍ ንህብ፣ ጉዳያት ኣሰራርሓ ንምልላይን ንምፍታሕን፣ ኣፈጻጽማን ቁጽጽርን ንምክትታል፣ ፍልጠት ንምትሕልላፍን ብቕዓት ኣብ ትካል ንምስራጽን ብምሕጋዝ።\nዕላማና ንዓኹም ምጅማር ጥራይ ምሕጋዝ ዘይኮነስ፣ ብዉጽኢታውነት ክሰርሕ፣ ንለውጢ ክላመድን ብዘላቕነት ክዓቢን ዝኽእል ትካል ሒዝኩም ንኽትተርፉ ምግባር እዩ።",
